insert into public.department_catalog(id,name,description,source_url) values ('gis','Gruppo d’Intervento Speciale (GIS)','Unità di intervento speciale dell’Arma, istituita nel 1978.','https://www.carabinieri.it/chi-siamo/oggi/organizzazione/mobile-e-speciale/2-brigata-mobile/gruppo-d%27intervento-speciale'),
('racis','Raggruppamento Carabinieri Investigazioni Scientifiche (Ra.C.I.S.)','Struttura di riferimento per polizia scientifica e supporto tecnico alle indagini.','https://www.carabinieri.it/chi-siamo/oggi/organizzazione/mobile-e-speciale/raggruppamento-carabinieri-investigazioni-scientifiche'),
('ros','Raggruppamento Operativo Speciale (ROS)','Struttura investigativa dell’Arma per indagini complesse e criminalità organizzata.','https://www.carabinieri.it/chi-siamo/oggi/organizzazione/mobile-e-speciale/raggruppamento-operativo-speciale'),
('tuscania','1° Reggimento Carabinieri Paracadutisti “Tuscania”','Reggimento paracadutisti dipendente dalla 2ª Brigata Mobile.','https://www.carabinieri.it/chi-siamo/oggi/organizzazione/mobile-e-speciale/2-brigata-mobile/1-reggimento-paracadutisti-tuscania') on conflict(id) do update set name=excluded.name,description=excluded.description,source_url=excluded.source_url;
insert into public.department_questions(department_id,rank_band,prompt,options,correct_index,explanation,sort_order) values ('gis',0,'In quale anno è stato istituito il GIS?','["1978","1984","1990","2002"]'::jsonb,0,'Il GIS è stato istituito il 6 febbraio 1978.',1),
